import{_ as a}from"./chunks/daily-2026-08-18-files-first-shared-ledger._Oq6pvn-.js";import{_ as n,C as o,o as s,c as i,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"多 Agent 治理为什么可以从文件开始？‘万物皆文件’的工程价值","description":"","frontmatter":{"title":"多 Agent 治理为什么可以从文件开始？‘万物皆文件’的工程价值","date":"2026-08-18","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"为什么文件、路径与事件适合作为本地优先多 Agent 治理的起点，它们又明确不保证什么？","summary":"文件不是消息队列或工作流引擎的廉价替代品；它的首要价值是先建立一份人和 Agent 都能检查的共同工作账本，再用真实压力决定是否升级基础设施。","item_id":"MANUAL-20260818-FILES","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-18-files-first-multi-agent-governance-cover.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-fact-matrices.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-18-guided-article-pipeline-round1/02-independent-editorial-review.md"]},"headers":[],"relativePath":"zh/engineering/2026-08-18-files-first-multi-agent-governance.md","filePath":"zh/engineering/2026-08-18-files-first-multi-agent-governance.md","lastUpdated":1787060190000}'),l={name:"zh/engineering/2026-08-18-files-first-multi-agent-governance.md"};function c(p,e,g,h,u,m){const t=o("ArticleCover");return s(),i("div",null,[r(t,{image:"/assets/covers/daily-2026-08-18-files-first-multi-agent-governance-cover.webp",kicker:"开源工程 · 研究文章",title:"多 Agent 治理为什么可以从文件开始？‘万物皆文件’的工程价值",summary:"文件不是消息队列或工作流引擎的廉价替代品；它的首要价值是先建立一份人和 Agent 都能检查的共同工作账本，再用真实压力决定是否升级基础设施。",version:"MANUAL-20260818-FILES",status:"Independent Editorial PASS · 2026-08-18",languageHref:"/en/engineering/2026-08-18-files-first-multi-agent-governance",languageLabel:"English"}),e[0]||(e[0]=d('<h1 id="多-agent-治理为什么可以从文件开始-万物皆文件-的工程价值" tabindex="-1">多 Agent 治理为什么可以从文件开始？“万物皆文件”的工程价值 <a class="header-anchor" href="#多-agent-治理为什么可以从文件开始-万物皆文件-的工程价值" aria-label="Permalink to &quot;多 Agent 治理为什么可以从文件开始？“万物皆文件”的工程价值&quot;">​</a></h1><blockquote><p>文件不是消息队列、数据库和工作流引擎的廉价替代品。它更适合承担第一份治理基础设施：一份人和 Agent 都能直接读取、检查、复制与恢复的工作账本。</p></blockquote><p>**系列导航：**本篇解释为什么从文件开始；接着阅读<a href="/joinwell52/zh/engineering/2026-08-18-fcop-file-state-machine">状态机实现篇</a>，再进入<a href="/joinwell52/zh/digital-employee/2026-08-18-cursor-ai-development-team">Cursor 团队实操篇</a>。三篇分别回答治理价值、协议内核和真实交付。</p><p>多 Agent 协作最先遇到的问题，不是怎样同时打开更多会话，而是怎样让一个角色交代的任务、另一个角色提交的结果、第三个角色给出的审查判断，成为所有参与者都能读取的共同事实。</p><p>如果这些内容只留在各自的上下文里，即使所有 Agent 都声称“完成”，团队仍可能回答不了几个最普通的问题：当前正式任务是哪一版？谁改了范围？测试报告对应哪次实现？驳回理由有没有进入下一轮任务？</p><p>很多系统在这一步会直接讨论更重的基础设施。但对于单机、本地优先、低到中等并发的 Agent 协作，第一步往往可以更朴素：先把任务、状态、回执和审查判断写成文件，让目录位置表达当前状态，让只追加事件保留迁移历史。</p><p>协议的核心只有一句话：</p><blockquote><p><strong>AI 角色之间不能只在脑子里说话，必须落成文件。</strong></p></blockquote><p>不是因为规定要求，是因为只有文件里的东西，才是真实发生过的协作。</p><p>“文件承载协议，路径表达状态，事件记录历史”是这句话的工程展开：文件让协作内容可以被其他角色读取，路径让当前状态可以被共同判断，事件让已经发生的迁移可以被追溯。</p><p>这不是“文件包打天下”。它是一条治理顺序：先让工作可见、可检查，再根据真实压力决定是否升级运行时。</p><h2 id="万物皆文件-真正值得借鉴的-不是口号" tabindex="-1">“万物皆文件”真正值得借鉴的，不是口号 <a class="header-anchor" href="#万物皆文件-真正值得借鉴的-不是口号" aria-label="Permalink to &quot;“万物皆文件”真正值得借鉴的，不是口号&quot;">​</a></h2><p>Ritchie 和 Thompson 在 <a href="https://pdos.csail.mit.edu/6.828/2014/readings/ritchie78unix.pdf" target="_blank" rel="noreferrer">The UNIX Time-Sharing System</a> 中描述的工程价值，比后来流行的口号更具体：Unix 用分层目录组织对象，尽量让普通文件、设备和进程间 I/O 共享兼容的读写接口；命令通过标准输入输出和 pipe 组合，而不要求每个程序理解所有上游和下游。</p><p>这里有三条可以迁移到 Agent 治理的原则。</p><p>第一，<strong>使用共同接口降低接入成本</strong>。人可以用编辑器读任务，Agent 可以解析 front matter，CLI 可以扫描目录，网页面板可以建立索引。它们不必先共享同一个 SDK 才能理解工作事实。</p><p>第二，<strong>让名称和位置携带稳定语义</strong>。路径不只是存储地址。<code>inbox/</code>、<code>active/</code>、<code>review/</code>、<code>done/</code> 可以成为人和程序都看得懂的状态面。</p><p>第三，<strong>把复杂能力放在可组合的小工具中</strong>。创建、校验、迁移、审查和归档可以由不同工具完成，只要它们遵守同一份工件契约。</p><p>但原论文也直接提醒我们不要神化文件：Unix 内部仍需要互锁；两个进程在没有锁、原子写或版本检查的情况下同时更新一个文件，可能造成内容损坏或更新丢失；pipe、process 和权限机制也不是“文件”二字自动提供的。因而本文采用的“万物皆文件”，只指<strong>优先把协作事实外化为通用、可读的工件</strong>，不指所有运行时问题都由文件系统解决。</p><h2 id="文件为什么适合做多-agent-的-黑板" tabindex="-1">文件为什么适合做多 Agent 的“黑板” <a class="header-anchor" href="#文件为什么适合做多-agent-的-黑板" aria-label="Permalink to &quot;文件为什么适合做多 Agent 的“黑板”&quot;">​</a></h2><p>H. Penny Nii 在 <a href="https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/537" target="_blank" rel="noreferrer">黑板模型</a> 中总结了一类经典问题求解架构：多个知识源围绕共享黑板读取当前问题状态，并把新的中间结果写回去。没有哪个知识源必须保存全局真相；协作发生在共享工作面上。</p><p>文件目录可以成为这种共享工作面的一个实现，但二者不能画等号。黑板可以放在内存或数据库里，文件也可能只是杂乱无章的日志。文件只有同时满足以下条件，才开始具有治理价值：</p><ol><li>每个工件有明确身份，而不是随手命名的笔记；</li><li>当前状态有唯一可判定的位置，而不是正文里互相冲突的 <code>status</code> 字段；</li><li>状态变化留下可排序事件，而不是移动后抹掉历史；</li><li>角色知道自己能创建、迁移和批准什么；</li><li>结束条件由可验证证据决定，而不是 Agent 的一句“已完成”。</li></ol><p>这也是“保存聊天记录”与“建立工作账本”的区别。聊天记录按说话顺序组织，工作账本按工作对象和责任组织。</p><p><img src="'+a+`" alt="多个角色写入同一文件、路径与事件事实面，再由人、Agent 和工具共同读取"></p><p><em>图 1：文件式治理首先建立共同事实面；它协调任务、状态和证据，但不替代执行引擎或分布式一致性系统。来源：Research Center 根据 Unix、FCoP 与 TMPA 资料整理。</em></p><h2 id="一份最小工作账本需要四类事实" tabindex="-1">一份最小工作账本需要四类事实 <a class="header-anchor" href="#一份最小工作账本需要四类事实" aria-label="Permalink to &quot;一份最小工作账本需要四类事实&quot;">​</a></h2><p>FCoP 使用四种 IPC envelope，把协作行为分成四类：</p><table tabindex="0"><thead><tr><th>工件</th><th>回答的问题</th><th>最小内容</th></tr></thead><tbody><tr><td><code>TASK</code></td><td>谁被要求交付什么？</td><td>sender、recipient、priority、parent、scope、acceptance</td></tr><tr><td><code>REPORT</code></td><td>执行者实际做了什么？</td><td>对应任务、变更、测试、剩余风险、证据路径</td></tr><tr><td><code>ISSUE</code></td><td>什么阻碍了交付？</td><td>现象、影响、已尝试动作、需要谁决策</td></tr><tr><td><code>REVIEW</code></td><td>谁基于什么证据作出什么判断？</td><td>subject、reviewer、verdict、理由、后续动作</td></tr></tbody></table><p>这四类工件不是四个聊天窗口。<code>TASK</code> 把角色之间的工作委托正式落盘；需要继续拆分时，下游任务通过 <code>parent</code> 指回上游任务。这样，任务从哪里来、交给了谁、怎样拆分以及最终回执给谁，都不必依赖某个 Agent 的会话记忆。</p><h2 id="五个生命周期桶-用文件位置回答-任务现在在哪" tabindex="-1">五个生命周期桶：用文件位置回答“任务现在在哪” <a class="header-anchor" href="#五个生命周期桶-用文件位置回答-任务现在在哪" aria-label="Permalink to &quot;五个生命周期桶：用文件位置回答“任务现在在哪”&quot;">​</a></h2><p><code>_lifecycle/</code> 下的五个目录不是为了整理得好看，而是一台最小、可观察的状态机：<strong>一张 TASK 在同一时刻只能位于一个桶中，移动文件就是状态迁移。</strong></p><table tabindex="0"><thead><tr><th>生命周期桶</th><th>回答的问题</th><th>典型动作</th></tr></thead><tbody><tr><td><code>inbox/</code></td><td>新任务已经落盘，谁来领取？</td><td>发送者或上游角色创建任务，等待接收者 <code>claim</code></td></tr><tr><td><code>active/</code></td><td>谁正在执行，或谁正在返工？</td><td>接收者认领；被驳回的任务也退回这里继续修改</td></tr><tr><td><code>review/</code></td><td>交付已经提交，谁来确认？</td><td>执行者提交，由上游角色或 <code>ADMIN</code> 审核</td></tr><tr><td><code>done/</code></td><td>协议生命周期是否已经完成或批准？</td><td><code>finish</code> 或 <code>approve</code>；但到达 <code>done</code> <strong>不等于业务验收完成</strong></td></tr><tr><td><code>archive/</code></td><td>这项工作是否已经退出当前协作面？</td><td>有权限的上游角色或 <code>ADMIN</code> 在接受交付后归档</td></tr></tbody></table><p>它形成一条能被人和程序同时读懂的主路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox --claim--&gt; active --submit--&gt; review --approve--&gt; done --archive--&gt; archive</span></span>
<span class="line"><span>                    |   ^                   |</span></span>
<span class="line"><span>                    |   +------reject-------+</span></span>
<span class="line"><span>                    +---------finish-------&gt;+</span></span></code></pre></div><p>五阶段桶的关键原理有四条：</p><ol><li><strong>单一当前位置</strong>：不能让同一张任务同时出现在 <code>active</code> 和 <code>done</code>，否则当前状态会出现两个答案。</li><li><strong>迁移而非改标签</strong>：状态改变通过受控移动完成，不靠 Agent 随手把正文里的 <code>status</code> 改成 <code>done</code>。</li><li><strong>现在与过去分层</strong>：文件路径回答“现在在哪”，TASK front matter 的 <code>transitions:</code> 只追加记录“怎样来到这里”。</li><li><strong>状态与凭证分离</strong>：<code>REPORT</code>、<code>ISSUE</code>、<code>REVIEW</code> 是交付、阻塞和治理判断的证据，不是任务当前状态。</li></ol><p>这里还必须澄清一个容易混淆的名称。FCoP v2 曾把 <code>tasks / reports / issues / shared / log</code> 称为“旧五桶”，那是按<strong>工件类型</strong>分目录；FCoP v3 已废止这种任务状态表达方式。本文所说的是 v3 <code>_lifecycle/</code> 下的<strong>五个生命周期桶</strong>，也就是按<strong>工作阶段</strong>组织 TASK。两者不是同一个概念。</p><p>同时，<code>_lifecycle/review/</code> 与 <code>reviews/REVIEW-*.md</code> 也不能混为一谈：前者表示 TASK 正在等待批准或驳回，后者是一份独立的治理判断工件。</p><p>于是，一份文件式工作账本包含三个相互配合、不能互相替代的层次：</p><ul><li>文件正文与四类工件说明“这是什么、做了什么、依据是什么”；</li><li>所在路径说明“这张任务现在位于哪个生命周期阶段”；</li><li><code>transitions:</code> 说明“它如何来到这里”。</li></ul><blockquote><p><strong>对于当前生命周期位置，路径才是唯一的 NOW 事实；对于业务是否完成，上游对 REPORT 及其证据的接受才是判断依据。</strong></p></blockquote><p>把三者压缩成一个可随意改写的 <code>status: done</code>，人就无法区分“执行者宣告完成”“任务被批准”和“上游真正接受交付”这三件不同的事。</p><h2 id="可检查性如何改变一次返工" tabindex="-1">可检查性如何改变一次返工 <a class="header-anchor" href="#可检查性如何改变一次返工" aria-label="Permalink to &quot;可检查性如何改变一次返工&quot;">​</a></h2><p>FCoP 仓库的 <a href="https://github.com/joinwell52-AI/FCoP/tree/a859e6747fe6e5e2d686e0114c77774726d7f748/docs/tutorials/assets/tetris-en/evidence" target="_blank" rel="noreferrer">Tetris dogfood 记录</a> 保存了一个小而真实的失败：任务规格不充分，执行者没有使用已有的 ISSUE 路径，而是自行猜测；缺陷随后出现在被猜测的区域。审查驳回后，管理员重新生成了一张范围更清楚的返工任务。</p><p>这个案例不能证明文件式治理能降低多少缺陷率，也不能外推到大型团队。它只证明一件较小但重要的事：当任务、执行回执、审查判断和返工任务分别存在时，失败不必只剩下一段模糊回忆。负责人可以追问：遗漏最早出现在哪份规格？执行者何时开始猜测？审查意见是否进入了下一张任务？</p><p>这就是工作账本带来的效果：不是消灭错误，而是<strong>让错误能够被定位、讨论和转化为下一步行动</strong>。</p><h2 id="文件起步适用于什么边界" tabindex="-1">文件起步适用于什么边界 <a class="header-anchor" href="#文件起步适用于什么边界" aria-label="Permalink to &quot;文件起步适用于什么边界&quot;">​</a></h2><p>文件式工作账本尤其适合这些条件：</p><ul><li>单机或明确的共享工作区；</li><li>任务吞吐量不高，人工可读性比毫秒级延迟更重要；</li><li>工件需要进入 Git、备份或普通文件工具链；</li><li>人需要直接检查、修订和批准 Agent 的工作；</li><li>团队仍在摸索协议，尚未稳定到值得建设复杂控制平面。</li></ul><p>出现下列压力时，则应把文件保留为证据面，同时升级运行时或索引层：</p><ul><li>多机对同一任务高频竞争；</li><li>需要严格事务、细粒度权限或复杂查询；</li><li>需要明确的重试、租约、超时调度和吞吐保证；</li><li>网络文件系统的缓存、一致性和故障语义无法满足要求；</li><li>工件规模使目录扫描和人工检索成为瓶颈。</li></ul><p>重点不是在“文件”和“重型系统”之间宣誓效忠，而是分清两个平面：<strong>工件平面负责留下可读事实，执行平面负责调度、隔离、重试和扩展。</strong> 两者可以从同一台机器上的一个目录开始，也可以逐步演化为不同组件。</p><h2 id="今天就能建立的最小结构" tabindex="-1">今天就能建立的最小结构 <a class="header-anchor" href="#今天就能建立的最小结构" aria-label="Permalink to &quot;今天就能建立的最小结构&quot;">​</a></h2><p>如果文章讨论的是 FCoP v3，就应该直接展示它的实际分层，而不是另造一个容易与协议混淆的 <code>events/</code> 目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>  fcop/</span></span>
<span class="line"><span>    fcop.json</span></span>
<span class="line"><span>    _lifecycle/</span></span>
<span class="line"><span>      inbox/</span></span>
<span class="line"><span>      active/</span></span>
<span class="line"><span>      review/</span></span>
<span class="line"><span>      done/</span></span>
<span class="line"><span>      archive/</span></span>
<span class="line"><span>    reports/</span></span>
<span class="line"><span>    issues/</span></span>
<span class="line"><span>    shared/</span></span>
<span class="line"><span>    reviews/</span></span>
<span class="line"><span>    history/</span></span>
<span class="line"><span>      YYYY-MM-DD/</span></span>
<span class="line"><span>  workspace/</span></span>
<span class="line"><span>    &lt;slug&gt;/</span></span></code></pre></div><p>这棵目录里有三个不同平面：</p><ul><li><code>_lifecycle/</code> 是 <strong>TASK 的当前状态面</strong>，五个子目录就是五个生命周期桶；</li><li><code>reports/</code>、<code>issues/</code>、<code>reviews/</code> 是 <strong>证据与治理面</strong>，它们不随 TASK 的状态迁移；</li><li><code>history/</code> 是 <strong>长期历史面</strong>，已关闭任务及其配对报告可以按日期进入深归档。</li></ul><p>每张 TASK 自身的 <code>transitions:</code> 保存只追加的迁移历史。因此不需要再创造一份可能与任务文件互相漂移的 <code>events/</code> 真相。其他系统当然可以把事件存入数据库或独立日志，但必须明确谁是权威来源。</p><p>再用七个问题检查它：</p><ol><li>每项工作是否有唯一身份和明确接收者？</li><li>人能否在一分钟内找到当前正式版本？</li><li>“完成”是否附带测试、diff 或其他环境证据？</li><li>审查判断是否与执行者回执分开保存？</li><li>驳回后是否生成了可追踪的下一步，而不是回到聊天里口头修改？</li><li>状态迁移是否保留时间、执行者和来源/去向？</li><li>如果运行时进程现在崩溃，重启后能否仅凭磁盘工件恢复“发生过什么”？</li></ol><p>若七个问题大多答不上来，系统缺少的通常不是更多 Agent，而是第一份共同工作账本。</p><h2 id="总结-万物皆文件-的工程价值到底是什么" tabindex="-1">总结：“万物皆文件”的工程价值到底是什么 <a class="header-anchor" href="#总结-万物皆文件-的工程价值到底是什么" aria-label="Permalink to &quot;总结：“万物皆文件”的工程价值到底是什么&quot;">​</a></h2><p>“万物皆文件”在多 Agent 治理中的价值，不是把数据库、消息队列和工作流引擎粗暴地换成 Markdown，而是先为协作建立一个统一、开放的协议面。它最终带来五项工程价值：</p><table tabindex="0"><thead><tr><th>工程价值</th><th>文件式账本如何提供它</th></tr></thead><tbody><tr><td><strong>可寻址</strong></td><td>每项任务有稳定文件名、发送者、接收者和父子关系，人和程序能指向同一个工作对象</td></tr><tr><td><strong>可观察</strong></td><td>五个生命周期桶直接暴露任务当前所在阶段，不必相信某个 Agent 的口头状态</td></tr><tr><td><strong>可回放</strong></td><td><code>transitions:</code> 保留迁移时间、来源、去向、执行者和工具，进程重启后仍能恢复历史</td></tr><tr><td><strong>可验证</strong></td><td>TASK、REPORT、ISSUE、REVIEW 分开落盘，让目标、执行回执、阻塞和独立判断能够互相核对</td></tr><tr><td><strong>可组合、可演化</strong></td><td>编辑器、Git、CLI、网页面板和索引器都能围绕同一批工件工作；并发和规模增加后，还可以在上面叠加数据库、队列与运行时</td></tr></tbody></table><p>可以把它压缩成一个公式：</p><blockquote><p><strong>稳定身份 + 路径状态 + 迁移历史 + 交付证据 = 一份可治理的共同工作账本。</strong></p></blockquote><p>这份账本不会自动解决并发竞争、事务、权限、重试和调度，但它先解决了更基础的问题：任务有没有被正式委托，谁正在负责，为什么被驳回，最终又凭什么被接受。</p><p>所以，“从文件开始”不是怀旧，也不是拒绝基础设施。它的工程价值是：<strong>先让人、Agent 和工具共享同一组可检查事实，再根据真实压力升级执行平面。</strong> 当瓶颈真的出现在竞争、查询、恢复、权限或吞吐上时，引入数据库、队列或工作流引擎才是有证据的演化，而不是一开始就用复杂系统掩盖协作事实仍然混乱的问题。</p><p>FCoP 不是行业标准，也不是最终答案。它提供的是一个可以被验证的起点：<strong>在增加控制平面之前，先让协作本身能够被人看见、被工具读取、被证据检查。</strong></p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://pdos.csail.mit.edu/6.828/2014/readings/ritchie78unix.pdf" target="_blank" rel="noreferrer">Ritchie &amp; Thompson, The UNIX Time-Sharing System</a></li><li><a href="https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/view/537" target="_blank" rel="noreferrer">H. Penny Nii, The Blackboard Model of Problem Solving and the Evolution of Blackboard Architectures</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038: FCoP Boundary Charter</a></li></ul>`,71))])}const A=n(l,[["render",c]]);export{v as __pageData,A as default};
